import os

from robot.utils.robottime import timestr_to_secs
from ute_common_interface.scope import ScopeController
from ute_common_store import Store
from ute_common_validator.validator import IsIpAddress, DoesFileExist, IsString, InRange
from ute_common_converter.to_number import ToInt
from .monitor import PerformanceMonitor
from .measurements import Measurements


class hran_pm(ScopeController):
    def __init__(self):
        super(hran_pm, self).__init__()
        self.pm_store = Store()
        self.measurements_store = Store()

    def setup_pm(self, host='192.168.255.1', timeout=20, **kwargs):
        """
        Setup performance monitor

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +------------------+------+---------------------------------------------------+
        | Parameter name   | Man. | Description                                       |
        +==================+======+===================================================+
        | scf_path         | yes  | kwargs, e.g.: scf_path="path/to/file"             |
        +------------------+------+---------------------------------------------------+
        | host             | no   | BTS ip address                                    |
        +------------------+------+---------------------------------------------------+
        | timeout          | no   | BTS ssh connection timeout                        |
        +------------------+------+---------------------------------------------------+
        """
        timeout = timestr_to_secs(timeout)
        IsIpAddress().check(host)
        ssh_connection_params = {
            'hostname': host,
            'port': 22,
            'username': 'toor4nsn',
            'password': 'oZPS0POrRieRtu',
            'timeout': timeout
        }
        alias = kwargs.get('alias')
        scf_path = kwargs.get('scf_path', '')
        DoesFileExist().check(scf_path)
        self.pm_store.add(PerformanceMonitor(ssh_connection_params, scf_path), alias)
        self.pm_store.get(alias).setup()

    def read_pm_file(self, **kwargs):
        """Load latest PM counters file from BTS.

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---
        """
        alias = kwargs.get('alias')
        self.pm_store.get(alias).read_pm_file_from_bts()

    def read_pm_file_for_wcdma(self, **kwargs):
        """Load latest PM file with WCDMA counters from BTS.

        | **Author:** iuliia.taupeka@nokia.com
        | **Maintainer:** iuliia.taupeka@nokia.com
        | **Released with version:** 2.8.0
        """
        alias = kwargs.get('alias')
        self.pm_store.get(alias).read_pm_file_for_wcdma_from_bts()

    def read_raw_pm_file(self, **kwargs):
        """Load latest RAW PM counters file from BTS.

        | **Author:** sebastian.burniak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---
        """
        alias = kwargs.get('alias')
        self.pm_store.get(alias).read_raw_pm_file_from_bts()

    def load_measurements(self, measurements_path, measurement_abbr_path, **kwargs):
        """
        Load measurement required to be checked.

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +------------------------+------+---------------------------------------------------------------+
        | Parameter name         | Man. | Description                                                   |
        +========================+======+===============================================================+
        | measurements_path      | yes  | Path to NIDD exported measurement file.                       |
        +------------------------+------+---------------------------------------------------------------+
        | measurement_abbr_path  | yes  | Path to measurement abbreviation dictionary.                  |
        +------------------------+------+---------------------------------------------------------------+
        | filtrate_key           | no   | optional argument with column names to filtrate               |
        |                        |      | counters in NIDD file                                         |
        +------------------------+------+---------------------------------------------------------------+
        | filtrate_value         | no   | optional argument with column values to                       |
        |                        |      | filtrate counters in NIDD file                                |
        +------------------------+------+---------------------------------------------------------------+
        """
        DoesFileExist().check(measurements_path)
        DoesFileExist().check(measurement_abbr_path)
        alias = kwargs.get('alias')
        paths = {'measurements': measurements_path,
                 'abbr': measurement_abbr_path}
        self.measurements_store.add(Measurements(), alias)
        self.measurements_store.get(alias).load_measurements(paths, **kwargs)

    def get_required_measurements(self, **kwargs):
        """
        Get all measurement names.

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **RETURN VALUE**
        Dictionary of all measurements with values provided in NIDD xls file.
        """
        alias = kwargs.get('alias')
        ms = self.measurements_store.get(alias)
        return ms.measurements

    def measurement_enabled_in_scf(self, measurement, **kwargs):
        """
        Check whether measurement is enabled on BTS.

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +------------------+------+----------------------------------------+
        | Parameter name   | Man. | Description                            |
        +==================+======+========================================+
        | measurement      | yes  | Full measurement name                  |
        +------------------+------+----------------------------------------+

        **RETURN VALUE**
        True if parameter value is non-zero in scf else False.
        """
        IsString().check(measurement)
        alias = kwargs.get('alias')
        ms = self.measurements_store.get(alias)
        abbr = ms.get_abbreviation(measurement)
        pm = self.pm_store.get(alias)
        return pm.enabled_in_scf(abbr)

    def get_scf_parameter(self, parameter_name, **kwargs):
        """
        Returns value of specified parameter.

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +------------------+------+----------------------------------------+
        | Parameter name   | Man. | Description                            |
        +==================+======+========================================+
        | parameter_name   | yes  | scf parameter name                     |
        +------------------+------+----------------------------------------+

        **RETURN VALUE**
        value of parameter
        """
        IsString().check(parameter_name)
        alias = kwargs.get('alias')
        pm = self.pm_store.get(alias)
        return pm.scf.get_parameter_by_name(parameter_name)

    def get_reporting_interval(self, **kwargs):
        """
        Returns PM report file creation time.

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **RETURN VALUE**
        Time in seconds
        """
        alias = kwargs.get('alias')
        pm = self.pm_store.get(alias)
        return pm.get_reporting_interval()

    def get_measurement_interval(self, measurement, **kwargs):
        """
        Returns counters collecting interval for specific measurement.

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +------------------+------+----------------------------------------+
        | Parameter name   | Man. | Description                            |
        +==================+======+========================================+
        | measurement      | yes  | Full measurement name                  |
        +------------------+------+----------------------------------------+

        **RETURN VALUE**
        Interval in seconds
        """
        IsString().check(measurement)
        alias = kwargs.get('alias')
        ms = self.measurements_store.get(alias)
        abbr = ms.get_abbreviation(measurement)
        pm = self.pm_store.get(alias)
        return pm.get_measurement_interval(abbr)

    def check_counters(self, numbers_list, occurrence=1, **kwargs):
        """
        Returns counters which number of occurrence is less than expected.
        Empty list if all required counters found.

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +------------------+------+-------------------------------------------------------+
        | Parameter name   | Man. | Description                                           |
        +==================+======+=======================================================+
        | numbers_list     | yes  | Counters numbers list for particular measurement type |
        +------------------+------+-------------------------------------------------------+
        | occurrence       | no   | Number of expected counters occurrence                |
        +------------------+------+-------------------------------------------------------+

        **RETURN VALUE**
        list of not present counters
        """
        alias = kwargs.get('alias')
        occurrence = ToInt().convert(occurrence)
        InRange(1, float('inf')).check(occurrence)
        pm = self.pm_store.get(alias)
        return pm.compare_counters(numbers_list, occurrence)

    def dump_pm_report(self, path='./PM_REPORT.xml', **kwargs):
        """
        Write loaded pm report to file.

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +------------------+------+----------------------------------------+
        | Parameter name   | Man. | Description                            |
        +==================+======+========================================+
        | path             | no   | destination file path                  |
        +------------------+------+----------------------------------------+
        """
        IsString().check(path)
        alias = kwargs.get('alias')
        self.pm_store.get(alias).dump_pm_to_file(path)

    def teardown_pm(self, **kwargs):
        """Teardown performance monitor. Loaded data will be lost.

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---
        """
        alias = kwargs.get('alias')
        self.pm_store.get(alias).teardown()
        self.pm_store.remove(alias)

    def teardown_measurements(self, **kwargs):
        """Clear loaded measurements files.

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---
        """
        alias = kwargs.get('alias')
        self.measurements_store.remove(alias)

    def teardown_all_aliases(self):
        """Clean up all hran_pm aliases.

        | **Author:** milosz.nowak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---
        """
        self._out_of_scope()

    def _out_of_scope(self):
        for alias in self.pm_store.aliases:
            self.teardown_pm(alias=alias)
        for alias in self.measurements_store.aliases:
            self.teardown_measurements(alias=alias)

    def check_counter_value(self, dn, counter_id, raw_value, **kwargs):
        """
        Checks if raw_value of counter_id value is equal raw_value.

        | **Author:** sebastian.burniak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** ---

        **Input Parameters:**

        +------------------+------+--------------------------------------------------------------+
        | Parameter name   | Man. | Description                                                  |
        +==================+======+==============================================================+
        | dn               | yes  | Dist name to parameter to check                              |
        +------------------+------+--------------------------------------------------------------+
        | counter_id       | yes  | Counter id to be checked                                     |
        +------------------+------+--------------------------------------------------------------+
        | raw_value        | yes  | Value declared in config file to be compared to actual value |
        +------------------+------+--------------------------------------------------------------+
        """
        alias = kwargs.get('alias')
        pm = self.pm_store.get(alias)
        scope = pm.counter_scope(str(raw_value))
        counter_value = pm.counter_value(dn, counter_id)
        return pm.compare_values(scope, counter_value, raw_value, counter_id)

    def get_newest_pm_file_name(self, **kwargs):
        """
        Get newest PM file name from BTS

        | **Author:** sebastian.burniak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** 2.2.0

        | **Full description:**
        | Get newest Performance Monitor file from /rom/uri/PERFMON_FILES

        **Example of simple usage:**

        .. code-block:: robotframework

           hran_pm.Setup_pm    scf_path="/home/ute/SCFC.xml"
           ${pm_file_name}=    hran_pm.get_newest_pm_file_name()

        """
        alias = kwargs.get('alias')
        pm = self.pm_store.get(alias)
        path_to_newest_file = pm.get_newest_pm_file_path()
        return os.path.basename(path_to_newest_file)

    def get_counter_value(self, dn, counter_id, start_time=None, interval=None, **kwargs):
        """
        Get counter value

        | **Author:** sebastian.burniak@nokia.com
        | **Maintainer:** sebastian.burniak@nokia.com
        | **Released with version:** 2.3.0

        | **Full description:**
        | Returns value of counter (defined in counter_id parameter) from
        | PM BTS file in destination name path (from given startTime and interval if provided as arguments)

        **Input Parameters:**

        +------------------+------+--------------------------------------------------------------------------------+
        | Parameter name   | Man. | Description                                                                    |
        +==================+======+================================================================================+
        | dn               | yes  | Destination Name path                                                          |
        +------------------+------+--------------------------------------------------------------------------------+
        | counter_id       | yes  | Counter identity on BTS (eg. M8010C36)                                         |
        +------------------+------+--------------------------------------------------------------------------------+
        | start_time       |  no  | Allow to get proper value of counter from the given startTime from PM.xml file |
        +------------------+------+--------------------------------------------------------------------------------+
        | interval         |  no  | Allow to get proper value of counter from the given interval from PM.xml file  |
        +------------------+------+--------------------------------------------------------------------------------+

        **Example of simple usage:**

        .. code-block:: robotframework

           hran_pm.Setup_pm     scf_path="/home/ute/SCFC.xml"
           hran_pm.read_pm_file
           ${counter_value}=    hran_pm.get_counter_value('PLMN-PLMN/RNC-36/WBTS-299', 'M5008C39')

         **Example of more complex usage:**

           .. code-block:: robotframework

           hran_pm.Setup_pm     scf_path="/home/ute/SCFC.xml"
           hran_pm.read_pm_file
           ${counter_value}=    hran_pm.get_counter_value('PLMN-PLMN/RNC-36/WBTS-299', 'M5008C39', 0, 15)

        """
        alias = kwargs.get('alias')
        pm = self.pm_store.get(alias)
        return pm.counter_value(dn, counter_id, start_time, interval)
